#include "platform/ps3/Ps3RasterRenderer.hpp"

#include <cstdio>
#include <cstring>

#include <ppu-types.h>
#include <rsx/rsx.h>

#include "platform/ps3/Ps3CubeMesh.hpp"
#include "platform/ps3/Ps3Vertex.hpp"
#include "platform/ps3/Ps3Video.hpp"

// Generated by the build from shaders/unlit.vcg and shaders/unlit.fcg through cgcomp
// and bin2s; the embedded program data is immutable.
#include "unlit_vpo.h"
#include "unlit_fpo.h"

namespace helengine::ps3 {
    Ps3RasterRenderer::Ps3RasterRenderer()
        : ContextValue(nullptr)
        , VertexProgram(nullptr)
        , VertexUcode(nullptr)
        , VertexUcodeBytes(0)
        , FragmentProgram(nullptr)
        , FragmentUcodeBuffer(nullptr)
        , FragmentUcodeOffset(0)
        , FragmentUcodeBytes(0)
        , ModelViewProjectionConstant(nullptr)
        , PositionAttributeIndex(0)
        , ColorAttributeIndex(0)
        , VertexBuffer(nullptr)
        , VertexBufferOffset(0)
        , VertexBufferBytes(0)
        , IndexBuffer(nullptr)
        , IndexBufferOffset(0)
        , IndexBufferBytes(0)
        , OwnedBytesValue(0)
        , DrawCounter(0)
        , Initialized(false) {
    }

    bool Ps3RasterRenderer::Initialize(Ps3Video& video) {
        if (Initialized) {
            std::printf("PS3_RENDERER_ERROR stage=initialize reason=already-initialized\n");
            return false;
        }
        ContextValue = video.Context();
        if (ContextValue == nullptr) {
            std::printf("PS3_RENDERER_ERROR stage=context reason=video-not-initialized\n");
            return false;
        }
        static_assert(sizeof(Ps3Vertex) == VertexStride, "vertex stride must match Ps3Vertex");

        VertexProgram = reinterpret_cast<const rsxVertexProgram*>(unlit_vpo);
        FragmentProgram = reinterpret_cast<const rsxFragmentProgram*>(unlit_fpo);
        rsxVertexProgramGetUCode(VertexProgram, &VertexUcode, &VertexUcodeBytes);
        if (VertexUcode == nullptr || VertexUcodeBytes == 0) {
            std::printf("PS3_SHADER_ERROR stage=vertex-ucode bytes=%u\n", VertexUcodeBytes);
            return false;
        }
        ModelViewProjectionConstant = rsxVertexProgramGetConst(VertexProgram, "mvp");
        if (ModelViewProjectionConstant == nullptr) {
            std::printf("PS3_SHADER_ERROR stage=reflect reason=mvp-constant-missing consts=%u\n",
                        static_cast<unsigned>(rsxVertexProgramGetNumConst(VertexProgram)));
            return false;
        }
        if (ModelViewProjectionConstant->type != PARAM_FLOAT4x4 || ModelViewProjectionConstant->count != 4) {
            std::printf("PS3_SHADER_ERROR stage=reflect reason=mvp-unexpected-layout type=%u count=%u\n",
                        static_cast<unsigned>(ModelViewProjectionConstant->type), static_cast<unsigned>(ModelViewProjectionConstant->count));
            return false;
        }
        if (!ReflectAttributes()) {
            return false;
        }

        void* fragmentUcode = nullptr;
        rsxFragmentProgramGetUCode(FragmentProgram, &fragmentUcode, &FragmentUcodeBytes);
        if (fragmentUcode == nullptr || FragmentUcodeBytes == 0) {
            std::printf("PS3_SHADER_ERROR stage=fragment-ucode bytes=%u\n", FragmentUcodeBytes);
            return false;
        }
        FragmentUcodeBuffer = rsxMemalign(FragmentUcodeAlignment, FragmentUcodeBytes);
        if (FragmentUcodeBuffer == nullptr) {
            std::printf("PS3_RENDERER_ERROR stage=fragment-alloc bytes=%u\n", FragmentUcodeBytes);
            return false;
        }
        OwnedBytesValue += FragmentUcodeBytes;
        std::memcpy(FragmentUcodeBuffer, fragmentUcode, FragmentUcodeBytes);
        const s32 fragmentOffsetResult = rsxAddressToOffset(FragmentUcodeBuffer, &FragmentUcodeOffset);
        if (fragmentOffsetResult != 0) {
            std::printf("PS3_RENDERER_ERROR stage=fragment-offset code=%d\n", fragmentOffsetResult);
            return false;
        }

        VertexBufferBytes = static_cast<u32>(Ps3CubeMesh::VertexCount) * static_cast<u32>(sizeof(Ps3Vertex));
        VertexBuffer = rsxMemalign(GeometryAlignment, VertexBufferBytes);
        if (VertexBuffer == nullptr) {
            std::printf("PS3_RENDERER_ERROR stage=vertex-alloc bytes=%u\n", VertexBufferBytes);
            return false;
        }
        OwnedBytesValue += VertexBufferBytes;
        std::memcpy(VertexBuffer, Ps3CubeMesh::Vertices(), VertexBufferBytes);
        const s32 vertexOffsetResult = rsxAddressToOffset(VertexBuffer, &VertexBufferOffset);
        if (vertexOffsetResult != 0) {
            std::printf("PS3_RENDERER_ERROR stage=vertex-offset code=%d\n", vertexOffsetResult);
            return false;
        }

        IndexBufferBytes = static_cast<u32>(Ps3CubeMesh::IndexCount) * static_cast<u32>(sizeof(u16));
        IndexBuffer = rsxMemalign(GeometryAlignment, IndexBufferBytes);
        if (IndexBuffer == nullptr) {
            std::printf("PS3_RENDERER_ERROR stage=index-alloc bytes=%u\n", IndexBufferBytes);
            return false;
        }
        OwnedBytesValue += IndexBufferBytes;
        std::memcpy(IndexBuffer, Ps3CubeMesh::Indices(), IndexBufferBytes);
        const s32 indexOffsetResult = rsxAddressToOffset(IndexBuffer, &IndexBufferOffset);
        if (indexOffsetResult != 0) {
            std::printf("PS3_RENDERER_ERROR stage=index-offset code=%d\n", indexOffsetResult);
            return false;
        }

        Initialized = true;
        std::printf("PS3_RENDERER_READY vertexUcodeBytes=%u fragmentUcodeBytes=%u vertexBytes=%u indexBytes=%u mvpIndex=%u mvpBase=%u positionAttrib=%u colorAttrib=%u ownedBytes=%u\n",
                    VertexUcodeBytes, FragmentUcodeBytes, VertexBufferBytes, IndexBufferBytes,
                    static_cast<unsigned>(ModelViewProjectionConstant->index), static_cast<unsigned>(VertexProgram->const_start),
                    static_cast<unsigned>(PositionAttributeIndex), static_cast<unsigned>(ColorAttributeIndex), OwnedBytesValue);
        return true;
    }

    bool Ps3RasterRenderer::ReflectAttributes() {
        const u16 attributeCount = rsxVertexProgramGetNumAttrib(VertexProgram);
        const rsxProgramAttrib* attributes = rsxVertexProgramGetAttribs(VertexProgram);
        bool positionFound = false;
        bool colorFound = false;
        for (u16 attribute = 0; attribute < attributeCount; ++attribute) {
            const char* name = reinterpret_cast<const char*>(reinterpret_cast<const u8*>(VertexProgram) + attributes[attribute].name_off);
            std::printf("PS3_SHADER_ATTRIB name=%s index=%u type=%u\n", name, static_cast<unsigned>(attributes[attribute].index), static_cast<unsigned>(attributes[attribute].type));
            if (attributes[attribute].index == GCM_VERTEX_ATTRIB_POS) {
                PositionAttributeIndex = GCM_VERTEX_ATTRIB_POS;
                positionFound = true;
            } else if (attributes[attribute].index == GCM_VERTEX_ATTRIB_COLOR0) {
                ColorAttributeIndex = GCM_VERTEX_ATTRIB_COLOR0;
                colorFound = true;
            }
        }
        if (!positionFound || !colorFound) {
            std::printf("PS3_SHADER_ERROR stage=reflect reason=attributes-missing position=%d color=%d count=%u\n",
                        positionFound ? 1 : 0, colorFound ? 1 : 0, static_cast<unsigned>(attributeCount));
            return false;
        }
        return true;
    }

    void Ps3RasterRenderer::UploadModelViewProjection(const Ps3Matrix4& modelViewProjection) {
        rsxSetVertexProgramParameter(ContextValue, VertexProgram, ModelViewProjectionConstant, modelViewProjection.Values);
    }

    bool Ps3RasterRenderer::Draw(const Ps3Matrix4& modelViewProjection) {
        if (!Initialized) {
            std::printf("PS3_RENDERER_ERROR stage=draw reason=not-initialized\n");
            return false;
        }
        rsxBindVertexArrayAttrib(ContextValue, PositionAttributeIndex, 0, VertexBufferOffset + PositionByteOffset, VertexStride, 3, GCM_VERTEX_DATA_TYPE_F32, GCM_LOCATION_RSX);
        rsxBindVertexArrayAttrib(ContextValue, ColorAttributeIndex, 0, VertexBufferOffset + ColorByteOffset, VertexStride, 4, GCM_VERTEX_DATA_TYPE_F32, GCM_LOCATION_RSX);
        rsxLoadVertexProgram(ContextValue, VertexProgram, VertexUcode);
        UploadModelViewProjection(modelViewProjection);
        rsxLoadFragmentProgramLocation(ContextValue, FragmentProgram, FragmentUcodeOffset, GCM_LOCATION_RSX);
        rsxSetDepthTestEnable(ContextValue, GCM_TRUE);
        rsxSetDepthFunc(ContextValue, GCM_LESS);
        rsxSetDepthWriteEnable(ContextValue, GCM_TRUE);
        rsxSetBlendEnable(ContextValue, GCM_FALSE);
        rsxSetShadeModel(ContextValue, GCM_SHADE_MODEL_SMOOTH);
        rsxSetFrontFace(ContextValue, GCM_FRONTFACE_CCW);
        rsxSetCullFace(ContextValue, GCM_CULL_BACK);
        rsxSetCullFaceEnable(ContextValue, GCM_TRUE);
        rsxSetUserClipPlaneControl(ContextValue, GCM_USER_CLIP_PLANE_DISABLE, GCM_USER_CLIP_PLANE_DISABLE, GCM_USER_CLIP_PLANE_DISABLE,
                                   GCM_USER_CLIP_PLANE_DISABLE, GCM_USER_CLIP_PLANE_DISABLE, GCM_USER_CLIP_PLANE_DISABLE);
        rsxDrawIndexArray(ContextValue, GCM_TYPE_TRIANGLES, IndexBufferOffset, static_cast<u32>(Ps3CubeMesh::IndexCount), GCM_INDEX_TYPE_16B, GCM_LOCATION_RSX);
        ++DrawCounter;
        if (DrawCounter == 1) {
            std::printf("PS3_FIRST_DRAW indices=%d vertices=%d\n", Ps3CubeMesh::IndexCount, Ps3CubeMesh::VertexCount);
        }
        return true;
    }

    bool Ps3RasterRenderer::UploadMesh(const Ps3Vertex* vertices, u32 vertexCount, const u16* indices, u32 indexCount, Ps3MeshBuffers& buffers) {
        buffers = Ps3MeshBuffers{ nullptr, 0, nullptr, 0, 0, 0 };
        if (!Initialized) {
            std::printf("PS3_MESH_ERROR stage=upload reason=renderer-not-initialized\n");
            return false;
        }
        if (vertices == nullptr || indices == nullptr || vertexCount == 0 || indexCount == 0 || (indexCount % 3) != 0) {
            std::printf("PS3_MESH_ERROR stage=upload reason=invalid-geometry vertices=%u indices=%u\n", vertexCount, indexCount);
            return false;
        }

        const u32 vertexBytes = vertexCount * static_cast<u32>(sizeof(Ps3Vertex));
        const u32 indexBytes = indexCount * static_cast<u32>(sizeof(u16));
        void* vertexBuffer = rsxMemalign(GeometryAlignment, vertexBytes);
        if (vertexBuffer == nullptr) {
            std::printf("PS3_MESH_ERROR stage=upload reason=vertex-alloc-failed bytes=%u\n", vertexBytes);
            return false;
        }
        u32 vertexOffset = 0;
        if (rsxAddressToOffset(vertexBuffer, &vertexOffset) != 0) {
            std::printf("PS3_MESH_ERROR stage=upload reason=vertex-offset-failed\n");
            rsxFree(vertexBuffer);
            return false;
        }
        void* indexBuffer = rsxMemalign(GeometryAlignment, indexBytes);
        if (indexBuffer == nullptr) {
            std::printf("PS3_MESH_ERROR stage=upload reason=index-alloc-failed bytes=%u\n", indexBytes);
            rsxFree(vertexBuffer);
            return false;
        }
        u32 indexOffset = 0;
        if (rsxAddressToOffset(indexBuffer, &indexOffset) != 0) {
            std::printf("PS3_MESH_ERROR stage=upload reason=index-offset-failed\n");
            rsxFree(indexBuffer);
            rsxFree(vertexBuffer);
            return false;
        }

        std::memcpy(vertexBuffer, vertices, vertexBytes);
        std::memcpy(indexBuffer, indices, indexBytes);
        buffers = Ps3MeshBuffers{ vertexBuffer, vertexOffset, indexBuffer, indexOffset, indexCount, vertexBytes + indexBytes };
        std::printf("PS3_MESH_UPLOADED vertices=%u indices=%u bytes=%u\n", vertexCount, indexCount, buffers.OwnedBytes);
        return true;
    }

    void Ps3RasterRenderer::ReleaseMesh(Ps3MeshBuffers& buffers) {
        if (buffers.IndexBuffer != nullptr) {
            rsxFree(buffers.IndexBuffer);
        }
        if (buffers.VertexBuffer != nullptr) {
            rsxFree(buffers.VertexBuffer);
        }
        buffers = Ps3MeshBuffers{ nullptr, 0, nullptr, 0, 0, 0 };
    }

    bool Ps3RasterRenderer::DrawIndexed(const Ps3MeshBuffers& buffers, const Ps3Matrix4& modelViewProjection) {
        if (!Initialized) {
            std::printf("PS3_RENDERER_ERROR stage=draw-indexed reason=not-initialized\n");
            return false;
        }
        if (buffers.IndexCount == 0 || buffers.VertexBuffer == nullptr || buffers.IndexBuffer == nullptr) {
            return false;
        }
        // Same pipeline and render state as the built-in cube; only the geometry differs.
        rsxBindVertexArrayAttrib(ContextValue, PositionAttributeIndex, 0, buffers.VertexBufferOffset + PositionByteOffset, VertexStride, 3, GCM_VERTEX_DATA_TYPE_F32, GCM_LOCATION_RSX);
        rsxBindVertexArrayAttrib(ContextValue, ColorAttributeIndex, 0, buffers.VertexBufferOffset + ColorByteOffset, VertexStride, 4, GCM_VERTEX_DATA_TYPE_F32, GCM_LOCATION_RSX);
        rsxLoadVertexProgram(ContextValue, VertexProgram, VertexUcode);
        UploadModelViewProjection(modelViewProjection);
        rsxLoadFragmentProgramLocation(ContextValue, FragmentProgram, FragmentUcodeOffset, GCM_LOCATION_RSX);
        rsxSetDepthTestEnable(ContextValue, GCM_TRUE);
        rsxSetDepthFunc(ContextValue, GCM_LESS);
        rsxSetDepthWriteEnable(ContextValue, GCM_TRUE);
        rsxSetBlendEnable(ContextValue, GCM_FALSE);
        rsxSetShadeModel(ContextValue, GCM_SHADE_MODEL_SMOOTH);
        rsxSetFrontFace(ContextValue, GCM_FRONTFACE_CCW);
        rsxSetCullFace(ContextValue, GCM_CULL_BACK);
        rsxSetCullFaceEnable(ContextValue, GCM_TRUE);
        rsxSetUserClipPlaneControl(ContextValue, GCM_USER_CLIP_PLANE_DISABLE, GCM_USER_CLIP_PLANE_DISABLE, GCM_USER_CLIP_PLANE_DISABLE,
                                   GCM_USER_CLIP_PLANE_DISABLE, GCM_USER_CLIP_PLANE_DISABLE, GCM_USER_CLIP_PLANE_DISABLE);
        rsxDrawIndexArray(ContextValue, GCM_TYPE_TRIANGLES, buffers.IndexBufferOffset, buffers.IndexCount, GCM_INDEX_TYPE_16B, GCM_LOCATION_RSX);
        ++DrawCounter;
        return true;
    }

    void Ps3RasterRenderer::Shutdown() {
        u32 freedBytes = 0;
        if (IndexBuffer != nullptr) {
            rsxFree(IndexBuffer);
            IndexBuffer = nullptr;
            freedBytes += IndexBufferBytes;
        }
        if (VertexBuffer != nullptr) {
            rsxFree(VertexBuffer);
            VertexBuffer = nullptr;
            freedBytes += VertexBufferBytes;
        }
        if (FragmentUcodeBuffer != nullptr) {
            rsxFree(FragmentUcodeBuffer);
            FragmentUcodeBuffer = nullptr;
            freedBytes += FragmentUcodeBytes;
        }
        Initialized = false;
        std::printf("PS3_RENDERER_SHUTDOWN freedBytes=%u ownedBytesBefore=%u draws=%u\n", freedBytes, OwnedBytesValue, DrawCounter);
        OwnedBytesValue -= freedBytes;
    }

    unsigned Ps3RasterRenderer::OwnedBytes() const {
        return OwnedBytesValue;
    }

    unsigned Ps3RasterRenderer::DrawCount() const {
        return DrawCounter;
    }
}
